{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Lipophilic pentacyclic triterpenoids/steroids such as lupeol, stigmasterol, and α-amyrin-acetate show log BB > 0.3, demonstrating that the triterpenoid scaffold can achieve BBB permeation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Ursolic acid and oleanolic acid, triterpenoid acids with a single carboxylate, are detected in brain after systemic administration, indicating that triterpenoid acids can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Oleanolic acid-derived esters reach micromolar brain Cmax after intraperitoneal dosing, showing that esterified triterpenoid acids can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Glycyrrhizin, the highly polar diglucuronide of glycyrrhetinic acid, shows low CSF-to-serum ratio in rats, indicating that very polar glycyrrhetinic acid conjugates have limited CNS access.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "Prednisolone-hemisuccinate, a water-soluble steroid hemisuccinate, is detected at extremely low CSF levels, illustrating poor BBB penetration for polar steroid hemisuccinates.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is carbenoxolone, a hemisuccinate ester of glycyrrhetinic acid. Although the closest analogue glycyrrhizin shows low CSF exposure, it is a much larger and more polar diglucuronide; the query is smaller, more lipophilic, and shares the pentacyclic triterpenoid core with multiple compounds experimentally shown to cross the BBB (oleanolic acid, ursolic acid, and esterified derivatives). The contradictory hemisuccinate evidence comes from a less lipophilic steroid scaffold and is outweighed by the triterpenoid CNS-penetration data. Prediction: pass.",
  "evidence_gaps": [
    "No direct carbenoxolone-specific brain or CSF concentration measurement is present in the evidence set.",
    "Potential prodrug hydrolysis of carbenoxolone to glycyrrhetinic acid and its contribution to CNS exposure is not directly quantified.",
    "Transporter-mediated efflux or uptake for the query is not experimentally characterized in the provided records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

